pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint128 amount) public {
        vm.assume(amount > 0);
        ReentrantObserver attacker = new ReentrantObserver(c);
        // fund the attacker's account via fallback so its balance is amount
        vm.deal(address(attacker), amount);
        // deposit by sending ether to the fallback from the attacker address
        vm.prank(address(attacker));
        (bool okDep, ) = address(c).call{value: amount}("");
        assertTrue(okDep);
        // drive withdraw from the re-entrant attacker
        attacker.attack();
        // General rule: at the moment of re-entry during withdraw, the caller's
        // balance getter still reported the full pre-withdraw balance (amount).
        // Reference C: effects after the call -> observes amount. Mutant: zeroed
        // before the call -> observes 0.
        assertTrue(attacker.observedBalance() == amount);
    }
}

contract ReentrantObserver {
    C public c;
    uint256 public observedBalance;

    constructor(C c_) { c = c_; }

    function attack() public {
        c.withdraw();
    }

    fallback() external payable {
        observedBalance = c.balances(address(this));
    }
}

