pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0) && uint256(uint160(actor)) > 0);
        amount = bound(amount, 1, 1e30);
        vm.assume(actor.code.length == 0); // plain caller; low-level call back to it succeeds

        // deposit via fallback
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool dep, ) = address(c).call{value: amount}("");
        assertTrue(dep);
        assertTrue(c.balances(actor) == amount);

        // first withdraw: succeeds in both versions
        vm.prank(actor);
        bool ok1;
        try c.withdraw() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1);
        assertTrue(c.balances(actor) == 0);

        // rule: after a successful withdraw, a subsequent withdraw (with any fresh deposit)
        // must still succeed for the same caller.
        vm.deal(actor, amount);
        vm.prank(actor);
        (bool dep2, ) = address(c).call{value: amount}("");
        assertTrue(dep2);

        vm.prank(actor);
        bool ok2;
        try c.withdraw() { ok2 = true; } catch { ok2 = false; }

        // general fact: withdrawals remain repeatable; balances of a withdrawer end at 0
        assertTrue(ok2 && c.balances(actor) == 0);
    }
}

