pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Actor actor;

    function setUp() public {
        c = new C();
        actor = new Actor();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint256).max / 2);
        address payable target = payable(address(c));

        // deposit via fallback
        vm.deal(address(actor), amount * 2);
        actor.deposit{value: amount}(target);

        // first withdraw succeeds on both P and M (lock is free initially)
        actor.withdraw(address(c));

        // RULE: after a successful withdraw, a second withdraw from the same
        // caller also succeeds (lock released). Mutant keeps lock set -> reverts.
        bool ok2 = actor.tryWithdraw(address(c));

        assertTrue(ok2, "second withdraw must succeed after the first");
    }
}

contract Actor {
    function deposit(address payable c) external payable {
        (bool ok, ) = c.call{value: msg.value}("");
        require(ok);
    }

    function withdraw(address c) external {
        C(c).withdraw();
    }

    function tryWithdraw(address c) external returns (bool) {
        try C(c).withdraw() {
            return true;
        } catch {
            return false;
        }
    }

    receive() external payable {}
}

