pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor1, address actor2) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(actor1 != address(0) && actor2 != address(0));
        vm.assume(actor1 != address(c) && actor2 != address(c));
        vm.assume(actor1 != actor2);

        // actor1 deposits via the payable fallback
        vm.deal(actor1, amount);
        vm.prank(actor1);
        address(c).call{value: amount}("");

        // actor1 withdraws successfully; the reference releases the lock afterwards
        vm.deal(actor1, amount);
        vm.prank(actor1);
        address(c).call(abi.encodeWithSelector(c.withdraw.selector));

        // a different address may still withdraw (zero balance, sends 0) —
        // the reference allows it; the buggy mutant's stuck lock makes it revert
        vm.prank(actor2);
        bool ok;
        try C(payable(address(c))).withdraw() {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

