pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 d, uint256 v, address victim) public {
        vm.assume(d > 0);
        vm.assume(v >= d);
        vm.assume(victim != address(0) && victim != address(c));

        Attacker a = new Attacker(address(c));

        // attacker funds its own account in C
        vm.deal(address(a), d);
        a.deposit(d);

        // a second depositor pads the contract so the re-entrant send can succeed
        vm.deal(victim, v);
        vm.prank(victim);
        (bool s, ) = address(c).call{value: v}("");
        require(s);

        // attacker withdraws; its receive() re-enters withdraw
        a.pwn();

        // P: reentrant withdraw is blocked by the lock, so the attempt reverts
        //    and the attacker's recorded balance is preserved.
        // M: reentrant withdraw succeeds and zeroes balances[attacker].
        assertTrue(c.balances(address(a)) == d, "balance preserved unless properly withdrawn");
    }
}

contract Attacker {
    C c;
    constructor(C target) { c = target; }
    function deposit() external payable {
        (bool s, ) = address(c).call{value: msg.value}("");
        require(s);
    }
    function pwn() external {
        c.withdraw();
    }
    receive() external payable {
        c.withdraw();
    }
}

