pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e18);

        Attacker a = new Attacker(c);

        // attacker records a balance of `amount` at its own address
        vm.deal(address(a), amount);
        a.fund();

        // contract is additionally funded so a second payout could succeed
        vm.deal(address(c), amount);
        uint256 preBalance = address(c).balance; // == 2 * amount

        // one withdraw through the re-entrant attacker
        a.attack();

        // general rule: after a withdraw, the contract's balance has decreased
        // by at most the withdrawn party's recorded balance
        assertTrue(address(c).balance >= preBalance - amount);
    }
}

contract Attacker {
    C c;
    constructor(C _c) { c = _c; }

    function fund() external payable {
        (bool s, ) = address(c).call{value: msg.value}("");
        require(s);
    }

    function attack() external {
        c.withdraw();
    }

    receive() external payable {
        // re-enter withdraw; ignore failure so the outer call still succeeds
        (bool s, ) = address(c).call(abi.encodeWithSignature("withdraw()"));
        s;
    }
}

