pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); attacker = new Attacker(c); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 100 ether);
        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}();
        require(c.balances(address(attacker)) == amount, "deposit failed");
        uint256 preBal = address(c).balance;
        attacker.go();
        // Rule: after the withdraw attempt, the depositor's recorded balance is either
        // still the full deposit (whole attempt reverted, reentrancy lock blocked the
        // nested call) or zero after exactly one full payout — but never paid out twice,
        // and the contract always retains >= preBal - amount.
        assertTrue(
            (c.balances(address(attacker)) == amount && address(c).balance == preBal)
            || (c.balances(address(attacker)) == 0 && address(c).balance == preBal - amount),
            "balance invariant broken"
        );
    }
}

contract Attacker {
    C c;
    uint256 reentered;
    constructor(C _c) { c = _c; }
    function deposit() external payable { } // uses fallback to credit balances
    function go() external { c.withdraw(); }
    receive() external payable {
        if (reentered == 0) {
            reentered = 1;
            c.withdraw();
        }
    }
    fallback() external payable {
        if (msg.value > 0) { // deposits routed here
            c.fallbackWithDeposit();
        }
    }
}

