pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;
    function setUp() public { c = new C(); attacker = new ReentrantAttacker(c); }
    function testFuzz_property(uint256 amount, uint256 extra, address funder) public {
        uint256 d = bound(amount, 1, 1e30);
        uint256 e = bound(extra, 0, 1e30);
        vm.deal(address(attacker), d);
        attacker.deposit();
        vm.deal(funder, e);
        vm.prank(funder);
        (bool dep, ) = address(c).call{value: e}("");
        assertTrue(dep);
        // A single withdraw may pay out each recorded balance exactly once, so the
        // non-participant funding e must survive the whole (possibly re-entrant) attack.
        attacker.attack();
        assertTrue(address(c).balance >= e);
    }
}

contract ReentrantAttacker {
    C c;
    bool once;
    constructor(C _c) { c = _c; }
    function deposit() external payable {
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok);
    }
    function attack() external { c.withdraw(); }
    receive() external payable {
        if (!once) { once = true; c.withdraw(); }
    }
}
